.tt {font-family:var(--font-sans);-webkit-font-smoothing:antialiased;letter-spacing:var(--tracking-snug);box-sizing:border-box;--sh-card:0 0 0 1px rgb(0 0 0/.3);--sh-plate:0 .5px 1px 1px rgb(0 0 0/.3);--sh-overlay:0 3px 8px rgb(0 0 0/.13),0 2px 5px rgb(0 0 0/.13),0 1px 1px rgb(0 0 0/.13);display:flex;align-items:center;gap:6px;width:fit-content;max-width:320px;border-radius:var(--radius-md);background:var(--color-popover);border:var(--spacing-hairline) solid var(--color-border-2);box-shadow:var(--sh-overlay);padding:4px 8px;font-size:var(--text-xs);font-weight:var(--font-weight-medium);text-wrap:balance;color:var(--color-foreground);letter-spacing:var(--tracking-normal)}
:where([data-doop-theme="light"]) .tt {--sh-card:0 0 0 .5px rgb(0 0 0/.11);--sh-plate:0 1px 2px rgb(0 0 0/.05);--sh-overlay:0 6px 18px rgb(0 0 0/.03),0 3px 9px rgb(0 0 0/.04),0 1px 1px rgb(0 0 0/.05);}
.tt .k {display:inline-flex;align-items:center;justify-content:center;height:16px;min-width:16px;border-radius:var(--radius-sm);background:var(--color-secondary);padding:0 4px;margin-right:-2px;font-family:var(--font-sans);font-size:var(--text-xs);font-weight:var(--font-weight-normal);color:var(--color-muted-foreground-1);white-space:nowrap}
